    {
      "node_code": "N_c1935d1c9d5fb9db",
      "definition": "指女性生殖系统发生的、需紧急医疗干预以挽救生命或防止严重并发症的急性病理状态，涵盖急腹症、大出血及急性感染等。",
      "boundary": "本节点聚焦于时间紧迫性高、病情进展快的妇科急性病变。包括异位妊娠破裂、卵巢囊肿蒂扭转、急性盆腔炎、子宫穿孔及产后大出血等。不包含慢性妇科疾病的急性发作（如慢性盆腔炎急性加重，若以慢性病史为主可归入炎症，若以急症处理为主归入本节点），也不包含非妇科来源的急腹症（如阑尾炎）。",
      "includes": [
        "异位妊娠破裂或流产伴大出血",
        "卵巢囊肿蒂扭转或破裂",
        "急性盆腔炎、子宫穿孔及妇科术后急性并发症"
      ],
      "excludes": [
        "慢性妇科疾病的非急性期管理",
        "非妇科来源的急腹症（如消化外科急症）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_e0fa0a05c24b93429",
          "rule": "本节点收录需紧急处理的急性感染或炎症（如急性盆腔炎）；妇科炎症与感染收录慢性、亚急性或常规感染的诊断治疗。"
        },
        {
          "other_code": "N_9834f26074c148c8",
          "rule": "本节点关注急症的临床识别与紧急处理原则；妇科手术关注具体的手术技术、术式选择及围手术期管理。"
        }
      ],
      "cross_boundary_rule": "当急症需通过手术解决时，若重点在于紧急决策与复苏归入本节点，若重点在于具体手术操作细节归入妇科手术。"
    },
    {
      "node_code": "N_9834f26074c148c8",
      "definition": "研究女性生殖系统疾病的手术治疗技术、术式选择、麻醉配合、围手术期管理及术后康复的临床医学分支。",
      "boundary": "本节点涵盖所有针对女性生殖器官的侵入性操作，包括开腹、腹腔镜、宫腔镜及阴道手术。内容涉及手术指征、具体操作步骤、并发症预防及术后护理。不包含非手术治疗方法（如药物治疗、物理治疗），也不包含产科分娩手术（如剖宫产，归入产科学）。",
      "includes": [
        "妇科良性及恶性肿瘤的根治性手术与微创手术",
        "宫腔镜、腹腔镜及阴道手术的具体技术与规范",
        "妇科手术的麻醉管理、围手术期护理及并发症处理"
      ],
      "excludes": [
        "非手术保守治疗（如药物、放疗）",
        "产科分娩相关手术（如剖宫产）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_c1935d1c9d5fb9db",
          "rule": "本节点关注手术技术本身及常规手术管理；妇科急症关注急性病理状态的紧急识别与初步处理。"
        },
        {
          "other_code": "N_1e01c6cb5a1c025d",
          "rule": "本节点提供通用的手术技术与原则；妇科肿瘤关注肿瘤特有的分期、综合治疗策略及预后评估。"
        }
      ],
      "cross_boundary_rule": "涉及肿瘤手术时，若重点在于手术技术细节归入本节点，若重点在于肿瘤综合治疗策略归入妇科肿瘤。"
    },
    {
      "node_code": "N_e0fa0a05c24b93429",
      "definition": "研究女性生殖系统由病原微生物引起的炎症性疾病及其诊断、治疗与预防的临床医学分支，涵盖上、下生殖道感染。",
      "boundary": "本节点聚焦于生殖道各部位的感染性病变，包括外阴、阴道、宫颈、子宫内膜、输卵管及盆腔腹膜。内容涉及病原体鉴定、抗生素使用原则、性传播疾病管理及慢性炎症的长期随访。不包含非感染性炎症（如自身免疫性），也不包含急性危及生命的急症处理（归入妇科急症）。",
      "includes": [
        "外阴阴道炎、宫颈炎及子宫内膜炎的诊断与治疗",
        "盆腔炎性疾病（PID）及性传播疾病（如淋病、衣原体感染）",
        "生殖道感染的病原体学基础及抗生素耐药性管理"
      ],
      "excludes": [
        "非感染性生殖系统炎症（如放射后炎症）",
        "急性危及生命的妇科急症（如急性盆腔炎伴休克，归入妇科急症）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_c1935d1c9d5fb9db",
          "rule": "本节点收录慢性、亚急性或常规感染的管理；妇科急症收录需紧急干预的急性感染或炎症并发症。"
        },
        {
          "other_code": "N_9941b699b2f820c5",
          "rule": "本节点关注感染性病因导致的病变；宫颈、阴道与外阴疾病关注该部位所有病因（包括肿瘤、发育异常等）的综合管理。"
        }
      ],
      "cross_boundary_rule": "当感染导致急性急症时，若以抗感染治疗为主归入本节点，若以紧急手术或复苏为主归入妇科急症。"
    }
  ]
}
